export class AdminEnvironmentsService {
    /**
     * List Admin Environments
     * List all agent environments across the platform (admin view).
     *
     * Returns enriched rows with owner info, template staleness, in-use flags,
     * and bundle install state. Filters for is_stale, in_use, and
     * update_available are applied after enrichment.
     * @param data The data for the request.
     * @param data.template Filter by template name (env_name)
     * @param data.status Filter by environment status
     * @param data.isStale Filter by staleness (current_image_tag != expected)
     * @param data.inUse Filter by in-use flag
     * @param data.updateAvailable Filter by bundle update availability (consumer install running an older revision than the bundle's latest)
     * @param data.ownerId Filter by agent owner user ID
     * @param data.search Search agent name, instance name, owner email/username
     * @param data.skip
     * @param data.limit
     * @returns AdminAgentEnvironmentsPublic Successful Response
     * @throws ApiError
     */
    public static listAdminEnvironments(data: AdminEnvironmentsListAdminEnvironmentsData = {}): CancelablePromise<AdminEnvironmentsListAdminEnvironmentsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/admin/agent-environments/',
            query: {
                template: data.template,
                status: data.status,
                is_stale: data.isStale,
                in_use: data.inUse,
                update_available: data.updateAvailable,
                owner_id: data.ownerId,
                search: data.search,
                skip: data.skip,
                limit: data.limit
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Bulk Rebuild Environments
     * Queue a rebuild for each environment in the request.
     *
     * Environments in transitional states are skipped (returned in skipped list).
     * Rebuilds run in parallel, throttled by ADMIN_BULK_REBUILD_CONCURRENCY.
     * Returns immediately; status updates arrive via ENVIRONMENT_STATUS_CHANGED events.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns AdminBulkRebuildResponse Successful Response
     * @throws ApiError
     */
    public static bulkRebuildEnvironments(data: AdminEnvironmentsBulkRebuildEnvironmentsData): CancelablePromise<AdminEnvironmentsBulkRebuildEnvironmentsResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/admin/agent-environments/bulk-rebuild',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Rebuild Single Environment
     * Trigger a rebuild for a single environment (admin path).
     *
     * Thin wrapper around the existing rebuild path; uses the superuser access
     * bypass so the admin can rebuild any user's environment.
     * @param data The data for the request.
     * @param data.envId
     * @returns Message Successful Response
     * @throws ApiError
     */
    public static rebuildSingleEnvironment(data: AdminEnvironmentsRebuildSingleEnvironmentData): CancelablePromise<AdminEnvironmentsRebuildSingleEnvironmentResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/admin/agent-environments/{env_id}/rebuild',
            path: {
                env_id: data.envId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
}

