export class AppAuthService {
    /**
     * List App Clients
     * List all active app clients registered by the authenticated user.
     * @returns DesktopOAuthClientPublic Successful Response
     * @throws ApiError
     */
    public static listAppClients(): CancelablePromise<AppAuthListAppClientsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/app-auth/clients'
        });
    }
    
    /**
     * Revoke App Client
     * Revoke an app client and all its refresh tokens.
     * @param data The data for the request.
     * @param data.clientId
     * @returns void Successful Response
     * @throws ApiError
     */
    public static revokeAppClient(data: AppAuthRevokeAppClientData): CancelablePromise<AppAuthRevokeAppClientResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/app-auth/clients/{client_id}',
            path: {
                client_id: data.clientId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Authorize
     * Public authorization endpoint — stores consent request and redirects to frontend.
     *
     * Identical to the desktop flow except the browser is redirected to the
     * ``/app-auth/consent`` SPA page. Does NOT require authentication; the consent
     * page uses its stored JWT to call ``POST /app-auth/consent``.
     *
     * Either client_id (existing client) or device_name (lazy registration) must
     * be provided so the consent page can display meaningful information.
     * @param data The data for the request.
     * @param data.redirectUri
     * @param data.codeChallenge
     * @param data.state
     * @param data.codeChallengeMethod
     * @param data.clientId
     * @param data.deviceName
     * @param data.platform
     * @param data.appVersion
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static authorize(data: AppAuthAuthorizeData): CancelablePromise<AppAuthAuthorizeResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/app-auth/authorize',
            query: {
                redirect_uri: data.redirectUri,
                code_challenge: data.codeChallenge,
                state: data.state,
                code_challenge_method: data.codeChallengeMethod,
                client_id: data.clientId,
                device_name: data.deviceName,
                platform: data.platform,
                app_version: data.appVersion
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Get App Auth Request
     * Return non-secret display metadata for a pending consent request.
     *
     * Public endpoint — no authentication required. Used by the frontend consent
     * page to render the device name, platform, app version, and client_kind
     * before the user approves or denies.
     *
     * Returns 404 if the nonce is unknown, already used, or expired.
     * @param data The data for the request.
     * @param data.nonce
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static getAppAuthRequest(data: AppAuthGetAppAuthRequestData): CancelablePromise<AppAuthGetAppAuthRequestResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/app-auth/requests/{nonce}',
            path: {
                nonce: data.nonce
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * App Consent
     * Process user consent for an app auth request.
     *
     * Requires authentication (the SPA calls this with its localStorage JWT).
     * Behaviour matches the desktop flow — see ``DesktopAuthService.process_consent``.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns ConsentResponse Successful Response
     * @throws ApiError
     */
    public static appConsent(data: AppAuthAppConsentData): CancelablePromise<AppAuthAppConsentResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/app-auth/consent',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Token Endpoint
     * Token endpoint — exchange authorization code or rotate refresh token.
     *
     * Accepts both ``application/x-www-form-urlencoded`` (OAuth 2.0 RFC 6749
     * standard) and ``application/json`` request bodies. Public (no auth). The
     * response includes client_id so lazy-registered clients learn their assigned
     * client_id after the first code exchange.
     * @returns TokenResponse Successful Response
     * @throws ApiError
     */
    public static tokenEndpoint(): CancelablePromise<AppAuthTokenEndpointResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/app-auth/token'
        });
    }
    
    /**
     * Userinfo
     * Return basic profile info for the authenticated user.
     *
     * Intended for Cinna Mobile clients to display "Connected as {name} ({email})"
     * after a successful token exchange. The access token is a standard JWT, so
     * this works with the same CurrentUser dependency as the rest of the API.
     * @returns UserInfoResponse Successful Response
     * @throws ApiError
     */
    public static userinfo(): CancelablePromise<AppAuthUserinfoResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/app-auth/userinfo'
        });
    }
    
    /**
     * Revoke
     * Revoke a client (and all its tokens) or a specific refresh token.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns void Successful Response
     * @throws ApiError
     */
    public static revoke(data: AppAuthRevokeData): CancelablePromise<AppAuthRevokeResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/app-auth/revoke',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Cinna App Discovery
     * Return instance metadata for Cinna Mobile app discovery.
     *
     * Mirrors /.well-known/cinna-desktop but points at the parallel /app-auth
     * surface. Endpoint field names follow RFC 8414 (OAuth 2.0 Authorization
     * Server Metadata): ``authorization_endpoint``, ``token_endpoint``,
     * ``userinfo_endpoint``.
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static cinnaAppDiscovery(): CancelablePromise<AppAuthCinnaAppDiscoveryResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/.well-known/cinna-app'
        });
    }
}

