export class DesktopAuthService {
    /**
     * List Desktop Clients
     * List all active desktop clients registered by the authenticated user.
     * @returns DesktopOAuthClientPublic Successful Response
     * @throws ApiError
     */
    public static listDesktopClients(): CancelablePromise<DesktopAuthListDesktopClientsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/desktop-auth/clients'
        });
    }
    
    /**
     * Revoke Desktop Client
     * Revoke a desktop client and all its refresh tokens.
     * @param data The data for the request.
     * @param data.clientId
     * @returns void Successful Response
     * @throws ApiError
     */
    public static revokeDesktopClient(data: DesktopAuthRevokeDesktopClientData): CancelablePromise<DesktopAuthRevokeDesktopClientResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/desktop-auth/clients/{client_id}',
            path: {
                client_id: data.clientId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Authorize
     * Public authorization endpoint — stores consent request and redirects to frontend.
     *
     * Does NOT require authentication. The browser navigates here directly, so the
     * JWT in localStorage cannot be included. Instead, we store the request by nonce
     * and redirect to the SPA consent page, which uses its stored JWT to call
     * POST /consent.
     *
     * Either client_id (existing client) or device_name (lazy registration) must
     * be provided so the consent page can display meaningful information.
     * @param data The data for the request.
     * @param data.redirectUri
     * @param data.codeChallenge
     * @param data.state
     * @param data.codeChallengeMethod
     * @param data.clientId
     * @param data.deviceName
     * @param data.platform
     * @param data.appVersion
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static authorize(data: DesktopAuthAuthorizeData): CancelablePromise<DesktopAuthAuthorizeResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/desktop-auth/authorize',
            query: {
                redirect_uri: data.redirectUri,
                code_challenge: data.codeChallenge,
                state: data.state,
                code_challenge_method: data.codeChallengeMethod,
                client_id: data.clientId,
                device_name: data.deviceName,
                platform: data.platform,
                app_version: data.appVersion
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Get Auth Request
     * Return non-secret display metadata for a pending consent request.
     *
     * Public endpoint — no authentication required. Used by the frontend consent
     * page to render the device name, platform, and app version before the user
     * approves or denies.
     *
     * Returns 404 if the nonce is unknown, already used, or expired.
     * @param data The data for the request.
     * @param data.nonce
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static getAuthRequest(data: DesktopAuthGetAuthRequestData): CancelablePromise<DesktopAuthGetAuthRequestResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/desktop-auth/requests/{nonce}',
            path: {
                nonce: data.nonce
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Consent
     * Process user consent for a desktop auth request.
     *
     * Requires authentication (the SPA calls this with its localStorage JWT).
     *
     * action="approve":
     * - Resolves or lazily creates the desktop client
     * - Issues a single-use authorization code
     * - Returns redirect URL with the code for the desktop app to capture
     * action="deny":
     * - Marks the request as used
     * - Returns redirect URL with error=access_denied
     * @param data The data for the request.
     * @param data.requestBody
     * @returns ConsentResponse Successful Response
     * @throws ApiError
     */
    public static consent(data: DesktopAuthConsentData): CancelablePromise<DesktopAuthConsentResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/desktop-auth/consent',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Token Endpoint
     * Token endpoint — exchange authorization code or rotate refresh token.
     *
     * Accepts both ``application/x-www-form-urlencoded`` (OAuth 2.0 RFC 6749
     * standard) and ``application/json`` request bodies. The endpoint is public
     * (no authentication required). The response includes client_id so desktop
     * apps using lazy registration learn their assigned client_id after the
     * first code exchange.
     * @returns TokenResponse Successful Response
     * @throws ApiError
     */
    public static tokenEndpoint(): CancelablePromise<DesktopAuthTokenEndpointResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/desktop-auth/token'
        });
    }
    
    /**
     * Userinfo
     * Return basic profile info for the authenticated user.
     *
     * Intended for Cinna Desktop clients to display "Connected as {name}
     * ({email})" after a successful token exchange. The desktop access token
     * is a standard JWT, so this endpoint works with the same CurrentUser
     * dependency as the rest of the API.
     * @returns UserInfoResponse Successful Response
     * @throws ApiError
     */
    public static userinfo(): CancelablePromise<DesktopAuthUserinfoResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/desktop-auth/userinfo'
        });
    }
    
    /**
     * Revoke
     * Revoke a client (and all its tokens) or a specific refresh token.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns void Successful Response
     * @throws ApiError
     */
    public static revoke(data: DesktopAuthRevokeData): CancelablePromise<DesktopAuthRevokeResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/desktop-auth/revoke',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Cinna Desktop Discovery
     * Return instance metadata for Cinna Desktop app discovery.
     *
     * Endpoint field names follow RFC 8414 (OAuth 2.0 Authorization Server
     * Metadata): ``authorization_endpoint``, ``token_endpoint``,
     * ``userinfo_endpoint``.
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static cinnaDesktopDiscovery(): CancelablePromise<DesktopAuthCinnaDesktopDiscoveryResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/.well-known/cinna-desktop'
        });
    }
}

