export class ExternalService {
    /**
     * List External Agents
     * Return all addressable targets for the authenticated user.
     *
     * Used by native clients to render their home screen agent list. Returns
     * three sections (personal agents, MCP shared agents, identity contacts)
     * in a single response, each with an ``agent_card_url`` pointing at the
     * target's A2A endpoint for chat.
     * @param data The data for the request.
     * @param data.workspaceId Optional workspace filter. When provided, limits the personal agents section to agents in this workspace. MCP shared agents and identity contacts are not filtered.
     * @returns ExternalAgentListResponse Successful Response
     * @throws ApiError
     */
    public static listExternalAgents(data: ExternalListExternalAgentsData = {}): CancelablePromise<ExternalListExternalAgentsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/external/agents',
            query: {
                workspace_id: data.workspaceId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Check External Install Updates
     * Reconcile and report installed-vs-latest bundle version for an install.
     *
     * Owner-gated. Delegates to the same ``InstallService.check_for_updates``
     * the web surface uses, so ``Agent.pending_update`` is reconciled and the
     * response matches the web client exactly. Native clients call this to
     * refresh a single agent's update state on demand (the discovery list
     * carries a read-only snapshot in ``bundle_version``).
     * @param data The data for the request.
     * @param data.agentId
     * @returns CheckUpdatesResponse Successful Response
     * @throws ApiError
     */
    public static checkExternalInstallUpdates(data: ExternalCheckExternalInstallUpdatesData): CancelablePromise<ExternalCheckExternalInstallUpdatesResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/external/agents/{agent_id}/check-updates',
            path: {
                agent_id: data.agentId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Apply External Install Update
     * Apply the latest bundle revision to an install from a native client.
     *
     * Owner-gated. Delegates to ``InstallService.apply_update`` (stops the
     * environment, swaps bundle-owned workspace content, preserves app-data /
     * credentials, restarts) and returns the post-update version state so the
     * client can refresh its UI without a second round-trip.
     * @param data The data for the request.
     * @param data.agentId
     * @returns BundleVersionInfo Successful Response
     * @throws ApiError
     */
    public static applyExternalInstallUpdate(data: ExternalApplyExternalInstallUpdateData): CancelablePromise<ExternalApplyExternalInstallUpdateResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/external/agents/{agent_id}/apply-update',
            path: {
                agent_id: data.agentId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * List External Sessions
     * Return all sessions where the current user is owner, caller, or identity_caller.
     *
     * Sessions are ordered by last_message_at DESC (most recent first). Covers
     * all integration types created via the external surface: "external" (personal
     * agents), "app_mcp" (shared agents), "identity_mcp" (identity contacts).
     *
     * Intended for native clients to restore their thread list at launch without
     * opening a full A2A connection per thread.
     *
     * Query params:
     * limit  — max results to return (default 100, capped inside the service)
     * offset — pagination offset (default 0)
     * @param data The data for the request.
     * @param data.limit
     * @param data.offset
     * @returns ExternalSessionPublic Successful Response
     * @throws ApiError
     */
    public static listExternalSessions(data: ExternalListExternalSessionsData = {}): CancelablePromise<ExternalListExternalSessionsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/external/sessions',
            query: {
                limit: data.limit,
                offset: data.offset
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Get External Session
     * Return metadata for a single session.
     *
     * Returns 404 if the session does not exist or the current user is not a
     * participant (owner, caller, or identity_caller). The 404 response is used
     * regardless of whether the session exists, to avoid leaking information
     * about sessions the user is not part of.
     * @param data The data for the request.
     * @param data.sessionId
     * @returns ExternalSessionPublic Successful Response
     * @throws ApiError
     */
    public static getExternalSession(data: ExternalGetExternalSessionData): CancelablePromise<ExternalGetExternalSessionResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/external/sessions/{session_id}',
            path: {
                session_id: data.sessionId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Hide External Session
     * Soft-hide a session from the caller's thread list.
     *
     * Sets ``session_metadata["hidden_for_callers"] = True`` on the session.
     * The session is NOT deleted from the database — it remains accessible to
     * the agent owner and for audit purposes.  After this call, the session will
     * no longer appear in ``GET /external/sessions`` for this caller.
     *
     * Returns 404 if the session does not exist or the current user is not a
     * participant (owner, caller, or identity_caller).
     *
     * Returns 204 No Content on success.
     * @param data The data for the request.
     * @param data.sessionId
     * @returns void Successful Response
     * @throws ApiError
     */
    public static hideExternalSession(data: ExternalHideExternalSessionData): CancelablePromise<ExternalHideExternalSessionResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/external/sessions/{session_id}',
            path: {
                session_id: data.sessionId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * List External Session Messages
     * Return message history for a visible session.
     *
     * Returns 404 if the session does not exist or the current user is not a
     * participant. Messages are returned in chronological order (oldest first).
     *
     * This endpoint is read-only — to send a new message use the A2A POST
     * endpoint for the session's target (``target.agent_card_url``).
     * @param data The data for the request.
     * @param data.sessionId
     * @returns MessagePublic Successful Response
     * @throws ApiError
     */
    public static listExternalSessionMessages(data: ExternalListExternalSessionMessagesData): CancelablePromise<ExternalListExternalSessionMessagesResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/external/sessions/{session_id}/messages',
            path: {
                session_id: data.sessionId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Get Account Config
     * Return the caller's own AI providers with decrypted keys (native only).
     *
     * Rejects non-native tokens with 403. Sets ``Cache-Control: no-store`` and
     * writes a high-severity audit event (no key material).
     * @returns AccountConfigResponse Successful Response
     * @throws ApiError
     */
    public static getAccountConfig(): CancelablePromise<ExternalGetAccountConfigResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/external/account-config'
        });
    }
}

