export class FilesService {
    /**
     * Upload File
     * Upload a file (creates temporary file record).
     *
     * Validates:
     * - File size (max 100MB)
     * - Mime type (whitelist)
     * - User storage quota (max 10GB)
     *
     * For guest users, the file is attributed to the agent owner.
     * @param data The data for the request.
     * @param data.formData
     * @returns FileUploadPublic Successful Response
     * @throws ApiError
     */
    public static uploadFile(data: FilesUploadFileData): CancelablePromise<FilesUploadFileResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/files/upload',
            formData: data.formData,
            mediaType: 'multipart/form-data',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Delete File
     * Mark file for deletion (soft delete).
     *
     * Authorization:
     * - File owner only (for guests, owner is the agent owner)
     * @param data The data for the request.
     * @param data.fileId
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static deleteFile(data: FilesDeleteFileData): CancelablePromise<FilesDeleteFileResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/files/{file_id}',
            path: {
                file_id: data.fileId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Download File
     * Download a file.
     *
     * Authorization (either is sufficient):
     * - A valid signed ``?token=`` whose ``file_id`` claim matches this file, OR
     * - a session JWT belonging to the file owner / a session participant / the
     * agent owner (for guests).
     *
     * ``?disposition=inline`` serves the file with ``Content-Disposition: inline``
     * for browser/in-place preview, but ONLY for a known-safe preview MIME set;
     * any other type (e.g. text/html, image/svg+xml) is forced to a download to
     * prevent same-origin script execution. The default is ``attachment``.
     *
     * All responses carry ``X-Content-Type-Options: nosniff``; inline responses
     * additionally carry a restrictive ``Content-Security-Policy``.
     * @param data The data for the request.
     * @param data.fileId
     * @param data.token Signed file-download token (alternative to a session JWT, used by A2A/native clients).
     * @param data.disposition Set to 'inline' to render the file in-place (preview); defaults to 'attachment' (download).
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static downloadFile(data: FilesDownloadFileData): CancelablePromise<FilesDownloadFileResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/files/{file_id}/download',
            path: {
                file_id: data.fileId
            },
            query: {
                token: data.token,
                disposition: data.disposition
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
}

