export class MfaService {
    /**
     * Mfa Status
     * Return whether 2FA is on for the current user and which factors
     * are enrolled.  Drives the Settings → Security tab header.
     * @returns MfaStatus Successful Response
     * @throws ApiError
     */
    public static mfaStatus(): CancelablePromise<MfaMfaStatusResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/users/me/mfa/status'
        });
    }
    
    /**
     * List Passkeys
     * List all registered passkeys for the current user.
     * @returns UserPasskeysPublic Successful Response
     * @throws ApiError
     */
    public static listPasskeys(): CancelablePromise<MfaListPasskeysResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/users/me/mfa/passkeys'
        });
    }
    
    /**
     * Begin Passkey Registration
     * Start the WebAuthn registration ceremony.
     *
     * Returns a :class:`BeginPasskeyRegistrationResponse` with the
     * ``PublicKeyCredentialCreationOptions`` nested under ``options`` plus
     * the ``challenge_token`` the client must echo back to ``finish``.
     *
     * The two are kept on separate keys so the frontend can pass ``options``
     * straight to ``@simplewebauthn/browser`` without contaminating the
     * spec-defined options object with our server-side challenge handle.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns BeginPasskeyRegistrationResponse Successful Response
     * @throws ApiError
     */
    public static beginPasskeyRegistration(data: MfaBeginPasskeyRegistrationData = {}): CancelablePromise<MfaBeginPasskeyRegistrationResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/passkeys/begin',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Finish Passkey Registration
     * Verify the WebAuthn attestation and persist the passkey.
     *
     * Response: ``{ "passkey": UserPasskeyPublic, "recovery_codes": [...] | None }``
     * where ``recovery_codes`` is populated only when this enrollment turns
     * 2FA on for the first time (so the UI knows to pop the one-shot
     * recovery-codes modal).
     * @param data The data for the request.
     * @param data.requestBody
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static finishPasskeyRegistration(data: MfaFinishPasskeyRegistrationData): CancelablePromise<MfaFinishPasskeyRegistrationResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/passkeys/finish',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Rename Passkey
     * Rename an owned passkey.
     * @param data The data for the request.
     * @param data.passkeyId
     * @param data.requestBody
     * @returns UserPasskeyPublic Successful Response
     * @throws ApiError
     */
    public static renamePasskey(data: MfaRenamePasskeyData): CancelablePromise<MfaRenamePasskeyResponse> {
        return __request(OpenAPI, {
            method: 'PATCH',
            url: '/api/v1/users/me/mfa/passkeys/{passkey_id}',
            path: {
                passkey_id: data.passkeyId
            },
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Delete Passkey
     * Delete an owned passkey.
     *
     * If the deleted passkey is the user's last remaining 2FA factor
     * (no other passkeys, no TOTP), 2FA is automatically turned off via
     * the same wipe-and-flag flow as ``POST /mfa/disable`` — the caller
     * does not need to make a separate disable call.
     * @param data The data for the request.
     * @param data.passkeyId
     * @returns Message Successful Response
     * @throws ApiError
     */
    public static deletePasskey(data: MfaDeletePasskeyData): CancelablePromise<MfaDeletePasskeyResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/users/me/mfa/passkeys/{passkey_id}',
            path: {
                passkey_id: data.passkeyId
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Begin Totp Enrollment
     * Generate a fresh TOTP secret and return the QR + otpauth URI.
     *
     * Nothing is persisted yet — the encrypted ``secret_token`` must be
     * echoed back to ``/finish`` along with a valid 6-digit code.
     * @returns TotpEnrollResponse Successful Response
     * @throws ApiError
     */
    public static beginTotpEnrollment(): CancelablePromise<MfaBeginTotpEnrollmentResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/totp/begin'
        });
    }
    
    /**
     * Finish Totp Enrollment
     * Persist the TOTP secret if the 6-digit code verifies.
     *
     * Mirrors :func:`finish_passkey_registration` — when this enrollment
     * turns 2FA on for the first time, the response contains a
     * ``recovery_codes`` block (one-shot).
     * @param data The data for the request.
     * @param data.requestBody
     * @returns unknown Successful Response
     * @throws ApiError
     */
    public static finishTotpEnrollment(data: MfaFinishTotpEnrollmentData): CancelablePromise<MfaFinishTotpEnrollmentResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/totp/finish',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Disable Totp
     * Remove the TOTP secret.  Requires a fresh-factor proof.
     *
     * If TOTP is the user's last remaining 2FA factor, 2FA is
     * automatically turned off via the same wipe-and-flag flow as
     * ``POST /mfa/disable``.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns Message Successful Response
     * @throws ApiError
     */
    public static disableTotp(data: MfaDisableTotpData): CancelablePromise<MfaDisableTotpResponse> {
        return __request(OpenAPI, {
            method: 'DELETE',
            url: '/api/v1/users/me/mfa/totp',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Recovery Codes Status
     * Return the remaining-count and last-regeneration timestamp.
     *
     * Never returns the plaintext codes — those are shown exactly once at
     * generation time.
     * @returns RecoveryCodeStatus Successful Response
     * @throws ApiError
     */
    public static recoveryCodesStatus(): CancelablePromise<MfaRecoveryCodesStatusResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/users/me/mfa/recovery-codes'
        });
    }
    
    /**
     * Regenerate Recovery Codes
     * Wipe the prior batch and mint a fresh set of plaintext recovery
     * codes.  Requires a fresh-factor proof.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns RecoveryCodesPlaintext Successful Response
     * @throws ApiError
     */
    public static regenerateRecoveryCodes(data: MfaRegenerateRecoveryCodesData): CancelablePromise<MfaRegenerateRecoveryCodesResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/recovery-codes/regenerate',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Begin Step Up Passkey
     * Issue a passkey step-up challenge.
     *
     * The frontend uses this to power the "use my passkey to confirm"
     * button on destructive actions (disable 2FA, regenerate recovery
     * codes, delete the last passkey).  The returned ``challenge_token``
     * must be supplied as ``passkey_challenge_token`` inside the
     * destructive request's ``StepUpProof`` body.
     * @returns StepUpPasskeyOptions Successful Response
     * @throws ApiError
     */
    public static beginStepUpPasskey(): CancelablePromise<MfaBeginStepUpPasskeyResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/step-up/passkey/options'
        });
    }
    
    /**
     * Disable Two Factor
     * Turn off 2FA — wipes ALL factors and the master flag.
     *
     * Requires a fresh factor proof; the access token alone is NOT enough.
     * @param data The data for the request.
     * @param data.requestBody
     * @returns Message Successful Response
     * @throws ApiError
     */
    public static disableTwoFactor(data: MfaDisableTwoFactorData): CancelablePromise<MfaDisableTwoFactorResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/users/me/mfa/disable',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
}

