export class SecurityEventsService {
    /**
     * Report Security Event
     * Blockable security event ingest.
     *
     * Logs the event and returns an action decision. Called synchronously by SDK
     * hooks — must respond quickly (hook has a 3-second timeout).
     *
     * The `action` field is the hook point for future policy logic. Currently
     * always returns "allow". When policy evaluation is added, "block" can be
     * returned here without any SDK-side changes.
     *
     * Auth: scoped agent-environment token (AgentEnvContextDep). The event is
     * attributed to the reporting env's agent/owner — the container-supplied
     * ``environment_id``/``agent_id`` in the body are ignored for attribution
     * (they are untrusted), so a compromised container cannot misattribute events
     * to another agent/env. ``session_id`` is retained as informational metadata.
     * @param data The data for the request.
     * @param data.requestBody
     * @param data.xAgentEnvId
     * @returns SecurityEventReportResponse Successful Response
     * @throws ApiError
     */
    public static reportSecurityEvent(data: SecurityEventsReportSecurityEventData): CancelablePromise<SecurityEventsReportSecurityEventResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/security-events/report',
            headers: {
                'x-agent-env-id': data.xAgentEnvId
            },
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * Ingest Security Event
     * Fire-and-forget security event ingest (non-blockable).
     *
     * Used for informational events like OUTPUT_REDACTED where the caller does
     * not wait for the response (asyncio.create_task pattern).
     *
     * Auth: AGENT_AUTH_TOKEN (agent environment JWT resolves to owning user)
     * @param data The data for the request.
     * @param data.requestBody
     * @returns SecurityEventPublic Successful Response
     * @throws ApiError
     */
    public static ingestSecurityEvent(data: SecurityEventsIngestSecurityEventData): CancelablePromise<SecurityEventsIngestSecurityEventResponse> {
        return __request(OpenAPI, {
            method: 'POST',
            url: '/api/v1/security-events/',
            body: data.requestBody,
            mediaType: 'application/json',
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
    /**
     * List Security Events
     * List security events for the current user.
     *
     * Results are paginated (default 50, max 200) and ordered newest first.
     * Optional filters: agent_id, environment_id, session_id, event_type.
     *
     * Auth: User JWT (for frontend audit view)
     * @param data The data for the request.
     * @param data.agentId
     * @param data.environmentId
     * @param data.sessionId
     * @param data.eventType
     * @param data.skip
     * @param data.limit
     * @returns SecurityEventsPublic Successful Response
     * @throws ApiError
     */
    public static listSecurityEvents(data: SecurityEventsListSecurityEventsData = {}): CancelablePromise<SecurityEventsListSecurityEventsResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/security-events/',
            query: {
                agent_id: data.agentId,
                environment_id: data.environmentId,
                session_id: data.sessionId,
                event_type: data.eventType,
                skip: data.skip,
                limit: data.limit
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
}

