    public static searchUsers(data: UsersSearchUsersData): CancelablePromise<UsersSearchUsersResponse> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/api/v1/users/search',
            query: {
                q: data.q,
                limit: data.limit,
                include_self: data.includeSelf
            },
            errors: {
                422: 'Validation Error'
            }
        });
    }
    
